def check_resource_partition(Q, Q_l, Q_g):
    # Check disjoint property
    if not set(Q_l).isdisjoint(set(Q_g)):
        return False
    # Check union property
    if not (set(Q_l).union(set(Q_g)) == set(Q)):
        return False
    return True

def calculate_B_t_non_preemptive(t, task_set):
    max_blocking = 0
    for task_x in task_set:
        if task_x.d > t:
            # Z_x is the max non-preemptive section length for task_x
            max_blocking = max(max_blocking, task_x.Z)
    return max_blocking

def calculate_pc_t(t, Q_l, task_set):
    min_pi_relevant = float('inf')
    for task_x in task_set:
        if task_x.d <= t:
            min_pi_relevant = min(min_pi_relevant, task_x.pi)

    pc_t = set()
    if min_pi_relevant == float('inf'): # No relevant tasks
        return pc_t

    for q in Q_l:
        if q.pi >= min_pi_relevant:
            pc_t.add(q)
    return pc_t

def calculate_B_t_ceiling(t, task_set, Q_l):
    pc_t_set = calculate_pc_t(t, Q_l, task_set) # Depends on pc_t definition
    max_blocking = 0
    for task_x in task_set:
        if task_x.d > t:
            for q in pc_t_set:
                # Assuming task_x.L_q is L_x_q
                max_blocking = max(max_blocking, task_x.L_q_map.get(q, 0))
    return max_blocking

def check_blocking_source(blocking_task, busy_period_length):
    if blocking_task.d > busy_period_length:
        return "Can cause arrival blocking"
    else:
        return "Cannot cause arrival blocking"

def calculate_total_arrival_blocking(B_t_non_preemptive, B_t_ceiling):
    # B_t_non_preemptive and B_t_ceiling already represent single max blocking instances
    return max(B_t_non_preemptive, B_t_ceiling)

def calculate_L_bound(task_set):
    U = sum(task.e / task.p for task in task_set)
    if U >= 1:
        return float('inf') # Unbounded busy-period

    max_d_i = max(task.d for task in task_set)

    sum_term = 0
    for task in task_set:
        sum_term += (task.e / task.p) * max(0, task.p - task.d)

    util_factor = 1 / (1 - U)

    return max(max_d_i, util_factor * sum_term)

def calculate_L_plus(tau_P_star, B_AC_function):
    L_current = min(task.e for task in tau_P_star) # Initial guess
    while True:
        demand = 0
        for task_i in tau_P_star:
            demand += (math.floor(L_current / task_i.p) * task_i.e)
        demand += B_AC_function(L_current) # B_AC_t is a function of t

        if demand == L_current:
            return L_current # Fixed point found
        elif demand < L_current:
            # This implies the processor is idle before L_current, so L_plus is smaller
            # In practice, the iteration L_new = Demand(L_old) converges or diverges.
            # If it converges, L_current will eventually equal demand.
            return L_current # Or the last L_current before demand < L_current
        else:
            L_current = demand # Continue iteration with new demand as next L_current

def causes_retry_delay(commit_i, commit_x, resource_q, commit_history):
    # Check if commit_x failed
    if not commit_x.succeeded:
        # Check if commit_i was the last successful commit to resource_q
        # before commit_x's failure attempt
        last_modifier = commit_history.get_last_modifier(resource_q, commit_x.failure_time)
        if last_modifier == commit_i:
            return True
    return False

class ConflictCounters:
    def __init__(self):
        self.Y_L = {}
        self.Y_R = {}

    def increment_local_conflict(self, task_i, task_j, resource_q, busy_period_t):
        key = (task_i, task_j, resource_q, busy_period_t)
        self.Y_L[key] = self.Y_L.get(key, 0) + 1

    def increment_remote_conflict(self, task_i, resource_q, busy_period_t):
        key = (task_i, resource_q, busy_period_t)
        self.Y_R[key] = self.Y_R.get(key, 0) + 1

def calculate_B_t_objective_lock_free(tau_P_star, Q, Y_R_map, Y_L_map, L_map, t):
    total_retry_delay = 0
    for task_i in tau_P_star:
        for resource_q in Q:
            remote_conflicts = Y_R_map.get((task_i, resource_q, t), 0)
            local_conflicts_sum = 0
            for task_j in tau_P_star:
                local_conflicts_sum += Y_L_map.get((task_i, task_j, resource_q, t), 0)

            commit_loop_length = L_map.get((task_i, resource_q), 0)
            total_retry_delay += (remote_conflicts + local_conflicts_sum) * commit_loop_length
    return total_retry_delay

class BlockingVariables:
    def __init__(self):
        self.X_S = {}
        self.X_A = {}
        self.A = {}

    def set_spin_contribution(self, task_i, resource_q, busy_period_t, fraction):
        self.X_S[(task_i, resource_q, busy_period_t)] = fraction

    def set_arrival_contribution(self, task_i, resource_q, busy_period_t, fraction):
        self.X_A[(task_i, resource_q, busy_period_t)] = fraction
        if fraction > 0:
            self.A[resource_q] = 1

    def get_A_q(self, resource_q):
        return self.A.get(resource_q, 0)

def calculate_B_t_objective_spin_lock(tau, Q, X_S_map, X_A_map, L_map, t):
    total_blocking_delay = 0
    for task_i in tau:
        for resource_q in Q:
            spin_contribution = X_S_map.get((task_i, resource_q, t), 0)
            arrival_contribution = X_A_map.get((task_i, resource_q, t), 0)

            critical_section_length = L_map.get((task_i, resource_q), 0)
            total_blocking_delay += (spin_contribution + arrival_contribution) * critical_section_length
    return total_blocking_delay

