def analyze_retry_causation(commit_i, commit_x):
    if commit_i.succeeded:
        return "commit_i does not retry due to commit_x"
    elif commit_x.succeeded:
        # If commit_i fails due to commit_x, it retries once.
        # commit_x is now done, so it cannot cause further retries for this specific instance.
        return "commit_x causes at most one retry of commit_i"
    else:
        return "No direct retry causation between these two specific instances"

def analyze_local_conflict_causation_by_job(job_J, resource_q, preempted_commit_loops_for_q):
    if not job_J.accesses_resource(resource_q):
        return 0 # No conflict caused

    num_conflicts_caused = 0
    # Conceptually, job_J's completion makes it the 'last modifier' for a moment.
    # Only one of the waiting commit loops can retry and succeed due to J.
    if len(preempted_commit_loops_for_q) > 0:
        num_conflicts_caused = 1 # At most one retry caused by J for this resource
    return num_conflicts_caused

def analyze_remote_conflict_causation(remote_commit_x, local_overlapping_commits):
    if not remote_commit_x.succeeded:
        return 0 # No conflict caused if remote commit failed

    num_conflicts_caused = 0
    # If remote_commit_x succeeded, it can cause at most one retry
    # among all local_overlapping_commits that were still pending.
    if len(local_overlapping_commits) > 0:
        num_conflicts_caused = 1
    return num_conflicts_caused

def apply_constraint_1(task_i, resource_q, N_i_q_map, Y_R_map, Y_L_map, t):
    if N_i_q_map.get((task_i, resource_q), 0) == 0:
        Y_R_map[(task_i, resource_q, t)] = 0
        for task_j in all_local_tasks:
            Y_L_map[(task_i, task_j, resource_q, t)] = 0

def apply_constraint_2(task_j, resource_q, N_j_q_map, Y_L_map, t):
    if N_j_q_map.get((task_j, resource_q), 0) == 0:
        for task_i in all_local_tasks:
            Y_L_map[(task_i, task_j, resource_q, t)] = 0

def apply_constraint_3(resource_q, tau_P_star, tau_R, nrjobs_map, N_map, Y_R_map, t):
    total_remote_accesses_to_q = 0
    for task_x in tau_R:
        total_remote_accesses_to_q += nrjobs_map.get((task_x, t), 0) * N_map.get((task_x, resource_q), 0)

    sum_Y_R_i_q_t = 0
    for task_i in tau_P_star:
        sum_Y_R_i_q_t += Y_R_map.get((task_i, resource_q, t), 0)

    # Constraint: sum_Y_R_i_q_t <= total_remote_accesses_to_q
    # In an ILP, this would be an inequality constraint.

def apply_constraint_4(task_i, nljobs_map, Q, Y_R_map, Y_L_map, t):
    if nljobs_map.get((task_i, t), 0) == 0:
        for resource_q in Q:
            Y_R_map[(task_i, resource_q, t)] = 0
            for task_j in all_local_tasks:
                Y_L_map[(task_i, task_j, resource_q, t)] = 0

def apply_constraint_5(task_i, task_j, nljobs_map, Q, Y_L_map, t):
    if task_j.d >= task_i.d:
        max_preemptions = 0
    else:
        max_preemptions = math.floor((task_i.d - task_j.d) / task_j.p)

    bound = max_preemptions * nljobs_map.get((task_i, t), 0)

    sum_Y_L_i_j_q_t = 0
    for resource_q in Q:
        sum_Y_L_i_j_q_t += Y_L_map.get((task_i, task_j, resource_q, t), 0)

    # Constraint: sum_Y_L_i_j_q_t <= bound

def apply_constraint_6(task_j, resource_q, tau_P_star, Y_L_map, t):
    bound = math.floor(t / task_j.p)

    sum_Y_L_i_j_q_t = 0
    for task_i in tau_P_star:
        sum_Y_L_i_j_q_t += Y_L_map.get((task_i, task_j, resource_q, t), 0)

    # Constraint: sum_Y_L_i_j_q_t <= bound

def apply_constraint_8(task_i, t, Q, X_A_map):
    if task_i.is_on_P_star and task_i.d <= t:
        for resource_q in Q:
            X_A_map[(task_i, resource_q, t)] = 0

def apply_constraint_9(task_i, Q, X_S_map, t):
    if task_i.is_on_P_star:
        for resource_q in Q:
            X_S_map[(task_i, resource_q, t)] = 0

def apply_constraint_11(Q, A_map):
    sum_A_q = 0
    for resource_q in Q:
        sum_A_q += A_map.get(resource_q, 0)

    # Constraint: sum_A_q <= 1

def apply_constraint_12(Q_l, pc_t_set, A_map):
    for resource_q in Q_l:
        if resource_q not in pc_t_set:
            A_map[resource_q] = 0

def apply_constraint_13(resource_q, Q, A_map, tau_P_star, N_map, t):
    sum_N_i_q_for_blocking_tasks = 0
    for task_i in tau_P_star:
        if task_i.d > t:
            sum_N_i_q_for_blocking_tasks += N_map.get((task_i, resource_q), 0)

    # Constraint: A_map.get(resource_q, 0) <= sum_N_i_q_for_blocking_tasks

def apply_constraint_15(P_k, P_star, resource_q, tau_P_k, tau_P_star, X_S_map, nljobs_map, N_map, t):
    total_local_requests_for_q = 0
    for task_i in tau_P_star:
        total_local_requests_for_q += nljobs_map.get((task_i, t), 0) * N_map.get((task_i, resource_q), 0)

    sum_X_S_x_q_t_remote = 0
    for task_x in tau_P_k:
        sum_X_S_x_q_t_remote += X_S_map.get((task_x, resource_q, t), 0)

    # Constraint: sum_X_S_x_q_t_remote <= total_local_requests_for_q

def apply_constraint_16(task_x, resource_q, tau_P_star, nrjobs_map, N_map, X_S_map, t):
    sum_local_requests_overlapping_d_x = 0
    for task_i in tau_P_star:
        sum_local_requests_overlapping_d_x += nrjobs_map.get((task_i, task_x.d), 0) * N_map.get((task_i, resource_q), 0)

    bound = nrjobs_map.get((task_x, t), 0) * sum_local_requests_overlapping_d_x

    # Constraint: X_S_map.get((task_x, resource_q, t), 0) <= bound

def apply_constraint_17(P_k, P_star, resource_q, tau_P_k, X_A_map, A_map, t):
    sum_X_A_x_q_t_remote = 0
    for task_x in tau_P_k:
        sum_X_A_x_q_t_remote += X_A_map.get((task_x, resource_q, t), 0)

    # Constraint: sum_X_A_x_q_t_remote <= A_map.get(resource_q, 0)

def PDC(P_k, t_LB, t_UB, Phi_k, B_PDC_function, task_set_P_k):
    for t in sorted(list(Phi_k)):
        if t_LB <= t <= t_UB:
            total_task_demand = 0
            for task_i in task_set_P_k:
                num_jobs = max(0, math.ceil((t + task_i.p - task_i.d) / task_i.p))
                total_task_demand += num_jobs * task_i.e

            if B_PDC_function(t) + total_task_demand > t:
                return False
    return True

def IS_CPU_SCHEDULABLE(P_k, B_AC_function, B_PDC_function, Phi_k, task_set_P_k):
    L_current = min(task.e for task in task_set_P_k) # Initial guess for busy-period length

    while True:
        # Calculate new busy-period length (L_plus_new) using arrival curve
        demand_sum = 0
        for task_i in task_set_P_k:
            demand_sum += (math.floor(L_current / task_i.p) * task_i.e)
        L_plus_new = B_AC_function(L_current) + demand_sum

        if L_current == L_plus_new:
            break # Fixed point converged

        # Check PDC for the newly extended interval [L_current, L_plus_new]
        if not PDC(P_k, L_current, L_plus_new, Phi_k, B_PDC_function, task_set_P_k):
            return False # Schedulability failed in this interval

        L_current = L_plus_new # Update for next iteration

    return True # All intervals checked, fixed point converged, schedulable
